/* ---------------- Study Topics ---------------- */
// Two kinds of list, as the app has them. "Questions": choosing a question loads it into the Theologian chat, ready to send but not sent.
// The other categories list curated topics: choosing one loads its content (overview, sub topics, sources as footnotes).
const QUESTIONS = [["God, Trinity, and Jesus", "How can Christians speak of one God, Father, Son, and Spirit, while also confessing Jesus as divine and human?"], ["Scripture, transmission, and trust", "Can an ancient collection copied, translated, and interpreted across centuries be read responsibly and trusted?"], ["Sin, salvation, and the cross", "What is sin, what does salvation mean, and why did Jesus die?"], ["Suffering, evil, and providence", "Why does suffering exist, what does God do about it, and how should providence and human freedom be understood?"], ["Violence, conquest, and slavery", "How should readers understand biblical texts involving conquest, violence, slavery, domination, or morally difficult social systems?"], ["Sexuality, LGBTQ interpretation, and relationships", "Why do Christians disagree about sexuality and LGBTQ inclusion, and what evidence is required to interpret the relevant texts responsibly?"], ["Women, ministry, and authority", "How should texts about women, leadership, household roles, teaching, and ministry be interpreted across their historical settings?"], ["Judgment, hell, resurrection, and final hope", "What do Christians mean by judgment, resurrection, hell, eternal life, and new creation, and why do final-destiny views differ?"], ["Other religions and the unevangelized", "How should Christians think about people of other religions, Jewish-Christian relations, and people who never encounter the Christian message?"], ["Miracles, history, and evidence", "How should claims about miracles and historical events be evaluated without either assuming or dismissing them in advance?"], ["Christian disagreement and traditions", "Why do sincere Christians reach different conclusions from shared texts, and how can traditions be compared fairly?"], ["Law, covenant, and Christian ethics", "Which biblical commands apply to Christians, how does covenant matter, and how should ethical application move from ancient text to modern life?"]];
const CATS = [['Questions', '12'], ['Theology & doctrine'], ['Christian life'], ['Biblical concepts'], ['Difficult questions']];
const CAT_NOTE = ['Start with a question, then inspect Scripture, context, and interpretation.', 'Belief, doctrine, salvation, Church, Spirit, and theological frameworks.', 'Prayer, ethics, worship, relationships, vocation, and discipleship.', 'Major biblical ideas and how they connect across Scripture.', 'Contested texts and questions handled with evidence labels and interpretive limits.'];
// Curated topics per category (title, overview, sub topics as [heading, text], sources). Copied from the app's catalog.
const ITEMS = [null, ...[[["What Christians mean by the Trinity", "Historic Christianity teaches that there is one God who is known as Father, Son, and Holy Spirit. Christians do not mean three gods, and they do not mean one person simply changing masks. “Three persons, one God” is technical language developed to hold together the Bible’s claims about God, Jesus, and the Spirit without collapsing any of them into the others.", [["Why Christians say this", "The doctrine grew from Christian worship and Scripture before it was expressed in later creeds. Christians prayed to the Father, confessed Jesus as divine, and experienced the Spirit as God’s active presence. The doctrine is an attempt to describe those claims together, not a mathematical explanation of God."], ["What it does not mean", "The Trinity is not three independent gods, a God divided into thirds, or one person taking turns being Father, Son, and Spirit. Every analogy eventually breaks down, so analogies should be treated as teaching aids rather than definitions."], ["Where Christians differ", "Most Catholic, Orthodox, Anglican, Lutheran, Reformed, Methodist, Baptist, Pentecostal, and many other churches affirm the historic doctrine. Some Christian movements reject or redefine it."]], ["Matthew 28:19", "John 1:1–18", "John 14–16"]], ["How Christians understand Jesus as human and divine", "Historic Christianity teaches that Jesus is fully human and fully divine. The point is not that Jesus is half of each. Christians believe the eternal Son truly entered human life: born, embodied, vulnerable, able to suffer and die, while still sharing in God’s identity.", [["Why it matters", "Christian claims about salvation depend on both sides of this confession. Jesus genuinely shares human life, while Christians also understand God to be acting personally in and through him."], ["A useful boundary", "Statements about Jesus’ hunger, grief, learning, suffering, authority, worship, or divine status should not be used to erase the other side of the confession."], ["Where Christians differ", "Christians debate how best to explain particular passages and how Jesus’ divine and human knowing relate, but the classic creedal position preserves both full humanity and full divinity."]], ["John 1:1–18", "Philippians 2:5–11", "Colossians 1:15–20"]], ["What Christians mean by salvation", "Salvation is the Christian claim that God acts through Jesus Christ to rescue people from sin and death, reconcile them to God, and bring them into renewed life. It is broader than “getting into heaven.” It includes forgiveness, reconciliation, liberation from destructive powers, transformed life, resurrection, and hope for renewed creation.", [["How it is received", "Christian traditions agree that salvation depends on God’s grace rather than human moral achievement. They describe the human response with language such as faith, repentance, trust, baptism, receiving grace, and persevering discipleship, while differing on how those pieces relate."], ["What good works do", "Good works are not a purchase price for God’s love. They are normally understood as the fruit or lived response of grace—love of neighbor, justice, mercy, repair, generosity, and growth in holiness."], ["Where Christians differ", "Traditions disagree about election, free will, sacraments, assurance, whether salvation can be finally rejected, and the final destiny of those outside explicit Christian faith."]], ["Ephesians 2:8–10", "Romans 3–8", "1 Corinthians 15"]], ["Why Christians say Jesus’ death saves", "The New Testament uses several images to explain why Jesus’ death matters: sacrifice, reconciliation, victory over sin and death, liberation, representation, ransom, covenant, and bearing sin. Christians agree that the cross is central to salvation but do not all reduce it to one mechanism.", [["Penal substitution", "One influential account says Christ bears the judgment or penalty sinners face. Many Christians find this biblically important; others emphasize that it should be held alongside the Bible’s other images rather than treated as the only explanation."], ["Victory and liberation", "Another major emphasis is that Christ confronts and defeats the powers of sin, death, and evil. The resurrection is essential to this picture: the cross is not simply a payment followed by an unrelated miracle."], ["Reconciliation", "The cross is also described as God acting to restore relationship. This image highlights forgiveness, peace, repaired communion, and a new way of life."]], ["Romans 3:21–26", "2 Corinthians 5:17–21", "Colossians 2:13–15"]]], [["What prayer is for", "Prayer is communication and relationship with God. In the Bible it includes praise, gratitude, requests, confession, silence, lament, anger, intercession, and surrender. It is not presented as a technique that guarantees a chosen outcome if performed correctly.", [["Unanswered prayer", "Biblical prayer includes requests that are delayed, changed, or apparently unanswered. Christianity therefore cannot responsibly promise that enough faith or the right words will produce healing, money, or a specific event."], ["How to begin", "You do not need special vocabulary. Say what is true: what you are grateful for, afraid of, angry about, responsible for, or hoping for. Silence can also be prayer."], ["Prayer and action", "Prayer can accompany practical action rather than replace it. Praying for someone’s needs while refusing reasonable help is a tension the New Testament itself notices."]], ["Matthew 6:5–13", "Psalm 13", "Romans 8:26–27"]], ["Forgiveness, reconciliation, and boundaries", "Christianity treats forgiveness as central, but forgiveness is not identical to pretending harm did not occur, restoring trust immediately, dropping every consequence, or returning to an unsafe relationship. Reconciliation requires more than one person; safety and accountability can remain necessary.", [["Forgiveness", "At minimum, forgiveness rejects vengeance as the final goal and opens the possibility that resentment will not control the future. Traditions describe its emotional and relational dimensions differently."], ["Reconciliation", "Reconciliation means repaired relationship and therefore normally requires truth, change, and participation by the people involved. It cannot be forced by one person alone."], ["Boundaries", "A person can seek to forgive while maintaining distance, reporting abuse, pursuing justice, or requiring demonstrated change before trust is restored."]], ["Matthew 18:15–35", "Luke 17:3–4", "Romans 12:17–21"]], ["What Christianity says about anxiety", "The Bible repeatedly invites people to bring fear and worry to God, but it does not teach that anxiety is proof of weak faith. Biblical people experience fear, distress, grief, sleeplessness, and anguish while still being portrayed as faithful. Christian care can include prayer, companionship, practical help, and appropriate professional treatment.", [["What “do not worry” is doing", "Jesus and Paul redirect attention toward trust, prayer, daily provision, and community. Those passages should not be weaponized as “a good Christian would stop feeling anxious.”"], ["Prayer and treatment", "Prayer is not a substitute for medical or mental-health care. Seeking appropriate treatment can be part of responsible care for a person."], ["A useful practice", "Name the concrete concern, identify what can be acted on today, ask for help where needed, and allow lament or uncertainty rather than demanding instant emotional change."]], ["Matthew 6:25–34", "Philippians 4:4–9", "Psalm 13"]], ["Work, calling, and purpose", "The Bible treats work as part of human responsibility before it treats work as toil. Christian vocation is therefore broader than finding one perfect career chosen by God. Paid work, caregiving, service, creativity, rest, and community responsibility can all belong to a meaningful life.", [["Calling is not a secret code", "Christians may experience a strong sense of calling, but Scripture does not require everyone to discover one hidden career path or assume a bad job choice permanently defeats God’s purpose."], ["Work can become unjust", "Biblical teaching also criticizes exploitation, withheld wages, status competition, and treating productivity as a measure of human worth."], ["Rest matters", "Sabbath traditions challenge the idea that a person’s value is equal to output. Rest, worship, relationships, and limits are also part of creaturely life."]], ["Genesis 2:15", "Deuteronomy 5:12–15", "Colossians 3:22–4:1"]]], [["What Christians mean when they call the Bible inspired", "Christians call Scripture inspired and authoritative because they believe God speaks through these writings to form faith and life. Christians disagree about exactly how inspiration relates to historical detail, scientific description, human authorship, textual transmission, and the word “inerrancy.”", [["Human and divine dimensions", "The Bible is a collection written in human languages, genres, cultures, and historical settings. Taking inspiration seriously does not remove the need to interpret those features."], ["Text and interpretation are not identical", "A Bible can be authoritative while a reader’s interpretation is mistaken. Translation decisions, manuscript evidence, genre, context, and theological assumptions all affect how a passage is understood."], ["Canon differences", "Protestant, Catholic, and Orthodox Bibles do not contain exactly the same Old Testament collection. That is a canon question, not simply a translation difference."]], ["2 Timothy 3:14–17", "Luke 1:1–4", "2 Peter 3:15–16"]], ["Why different Bibles contain different books", "“Canon” means the collection a religious community recognizes as Scripture. Protestant Bibles normally contain 66 books. Catholic Bibles include additional Old Testament books, and Orthodox traditions include somewhat different collections. This difference is about which writings belong in the recognized collection, not simply which English translation is used.", [["Why the collections differ", "Jewish and Christian communities inherited, used, translated, and formally recognized ancient writings through different historical processes. The boundaries were not created by one single modern decision."], ["How this app handles it", "The Canonical Shelf teaches the 66-book Protestant arrangement as its navigation system while explicitly acknowledging that it is not the only Christian canon."]], ["Luke 24:44", "2 Timothy 3:14–17"]], ["Why Bible translations sound different", "Bible translations differ because translators must make choices about ancient Hebrew, Aramaic, and Greek wording, style, ambiguity, and how directly to reproduce ancient sentence structure. Different wording is not automatically evidence of corruption.", [["More literal vs more explanatory", "Some translations preserve source-language structure more closely; others prioritize natural modern English. Neither approach removes interpretation."], ["Manuscript differences", "A smaller number of differences come from variation among surviving ancient manuscripts. Modern editions compare those witnesses and often place significant variants in footnotes."], ["How to compare responsibly", "Read the whole paragraph, compare two or three reputable translations, and inspect notes when an argument depends heavily on one wording."]], ["Luke 1:1–4", "1 John 5:6–8"]], ["Why genre changes how you read the Bible", "The Bible contains narrative, law, poetry, wisdom, prophecy, letters, genealogy, parable, and apocalyptic vision. Reading responsibly means asking what kind of writing you are reading before deciding what a sentence is doing. “Take the Bible seriously” is not the same as “read every sentence as the same kind of literal statement.”", [["Examples", "A proverb describes wise patterns; a psalm may use metaphor; a letter addresses a concrete community; a parable tells a story to provoke understanding; Revelation uses symbolic visions. Each can communicate truth without using the same method."], ["Genre is not an escape hatch", "Calling something poetic or symbolic does not mean it can mean anything. Literary form still has evidence, structure, context, and interpretive limits."]], ["Psalm 18:1–6", "Proverbs 26:4–5", "Luke 15"]]], [["Why suffering exists", "Christianity does not have one sentence that explains every instance of suffering. Scripture contains several kinds of explanation: human wrongdoing, unjust systems, ordinary creaturely vulnerability, consequences, spiritual evil, and suffering whose reason remains unknown. Job explicitly resists the idea that every tragedy can be reverse-engineered into the victim’s fault.", [["Freedom and evil", "Many Christians argue that meaningful freedom makes genuine wrongdoing possible. That helps explain some moral evil but does not by itself explain disease, disaster, or every unanswered prayer."], ["God and tragedy", "Christians may believe God can redeem suffering without calling the harmful event itself good. The Bible also gives people permission to lament rather than explain."], ["Pastoral boundary", "Do not tell a suffering person that pain proves weak faith or that you know God deliberately caused their specific tragedy."]], ["Job 1–2; 38–42", "Psalm 22", "Luke 13:1–5"]], ["Christianity and LGBTQ people", "Christians disagree about how a small group of biblical passages applies to modern LGBTQ identities and relationships. This course takes an affirming position: LGBTQ people can fully belong, marry, lead, serve, and participate in Christian community without treating their identity as a defect to be cured.", [["Why Christians disagree", "The debate involves translation, ancient sexual practices, creation texts, assumptions about gender, how biblical commands apply across cultures, and how Christians use Jesus’ teaching, covenant, justice, and the wider scriptural story."], ["What an affirming reading argues", "Affirming Christians argue that the biblical texts often cited against LGBTQ people address situations that are not equivalent to loving, mutual modern same-sex relationships or transgender identity, and that Christian sexual ethics should focus on covenant, fidelity, justice, consent, and neighbor-love."], ["What non-affirming Christians argue", "Non-affirming Christians commonly understand the relevant texts and creation patterns as establishing male–female marriage as the permitted context for sex. This course explains that position without adopting it."]], ["Genesis 1–2", "Matthew 22:34–40", "Acts 10–15"]], ["Violence, self-defense, war, and Christian disagreement", "Christians agree that human life has dignity and that violence is morally serious, but traditions disagree about whether force can be justified to protect others or restrain grave wrongdoing. Historic positions include Christian pacifism/nonviolence and just-war traditions with strict limits; neither should be reduced to a slogan.", [["Jesus and enemy-love", "Jesus’ teaching about enemy-love and nonretaliation is central to Christian pacifist arguments and constrains any Christian account of violence."], ["Protection of others", "Just-war and limited-force traditions argue that love of neighbor can include protecting people from aggression, while requiring legitimate authority, proportionality, discrimination between combatants/noncombatants, and last-resort reasoning."], ["Biblical violence", "Conquest and warfare texts require historical, literary, and theological study. They should not be converted into authorization for modern religious violence."]], ["Matthew 5:38–48", "Romans 12:14–21", "Romans 13:1–7"]], ["What Christians mean by miracles", "Biblical miracle stories present unusual acts of divine power or signs that reveal something about God’s reign, compassion, judgment, or identity. Christians disagree about how frequently miraculous gifts occur today and how claims should be evaluated. The course treats miracle accounts seriously without encouraging credulity toward every modern claim.", [["Signs have meaning", "In the Gospels, healings and other signs are not spectacle alone; they are tied to compassion, authority, restoration, and the announcement of God’s kingdom."], ["Modern claims", "A claim of healing or miracle should not be insulated from evidence. Medical care should not be abandoned because a miracle is hoped for."], ["Unhealed people", "Failure to receive a desired healing is not evidence that a person lacked faith or moral worth."]], ["Mark 2:1–12", "John 9", "John 20:30–31"]]]]];
const REF_GROUP = { Matthew: 'gospels', Mark: 'gospels', Luke: 'gospels', John: 'gospels', Acts: 'gospels', Romans: 'paul', Corinthians: 'paul', Galatians: 'paul', Ephesians: 'paul', Philippians: 'paul', Colossians: 'paul', Thessalonians: 'paul', Timothy: 'paul', Titus: 'paul', Philemon: 'paul', Genesis: 'law', Exodus: 'law', Leviticus: 'law', Numbers: 'law', Deuteronomy: 'law', Psalm: 'wisdom', Psalms: 'wisdom', Proverbs: 'wisdom', Job: 'wisdom', Isaiah: 'major', Jeremiah: 'major', Hebrews: 'general', James: 'general', Peter: 'general', Revelation: 'revelation' };
