const topicsHeading = cat => `<div class="cs-heading"><span class="cs-kicker">Study Topics</span><h1>${CATS[cat][0]}</h1><span class="cs-sub">${CAT_NOTE[cat]}</span></div>`;
const questionCards = `<div class="cs-topic-grid">${QUESTIONS.map(([t, d], n) => `<a class="cs-topic" href="#" data-go="view=q;topic=${n}"><span class="cs-topic__title">${t}</span><span class="cs-topic__text">${d}</span></a>`).join('')}</div><span class="cs-result-count" aria-live="polite">Showing 12 of 12 questions</span>`;
const itemCards = (cat, k) => `<div class="cs-topic-grid">${items(cat).map(([t, d], n) => `<a class="cs-topic" href="#" data-go="topic=${n};sub=0"${n === k ? ' aria-current="true"' : ''}><span class="cs-topic__title">${t}</span><span class="cs-topic__text">${d.length > 130 ? d.slice(0, d.lastIndexOf(' ', 127)).replace(/[.,;:]+$/, '') + '…' : d}</span></a>`).join('')}</div><span class="cs-result-count" aria-live="polite">Showing ${items(cat).length} of ${items(cat).length} topics</span>`;
const refList = refs => `<ul class="cs-refs">${refs.map(r => `<li data-group="${refGroup(r)}"><span class="cs-refs__bar"></span><div class="cs-grow"><div class="cs-refs__head"><a href="?screen=reader">${r}<span class="cs-visually-hidden">, ${GROUPS[refGroup(r)]}</span></a></div></div></li>`).join('')}</ul>`;
const viewsList = () => `<dl class="cs-terms">${otherViews.map(([a, b]) => `<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
