// Desktop: the category list stays on the left. Questions fill the middle and have no right pane. A curated topic's overview, sub topics, text and sources are on the right.
const itemPane = (cat, k, j) => { const [t, a, subs, refs] = items(cat)[k], s = subs[j]; return `<aside class="cs-stack" aria-label="Selected topic"><section class="cs-card cs-panel cs-topic-detail"><span class="cs-caption cs-caption--label">Overview</span><h2>${t}</h2><p>${a}</p></section><section class="cs-card cs-panel"><span class="cs-caption cs-caption--label">Sub topics</span><nav class="cs-sublist" aria-label="Sub topics">${subs.map(([h], n) => `<a href="#" data-go="sub=${n}"${n === j ? ' aria-current="true"' : ''}><span class="cs-sublist__num">${n + 1}</span>${h}</a>`).join('')}</nav></section><section class="cs-card cs-panel cs-subbody"><span class="cs-caption cs-caption--label">${s[0]}</span><p>${s[1]}</p><span class="cs-caption cs-caption--label">Sources</span>${refList(refs)}</section>${studiedCard()}${askCard(t)}</aside>`; };
